// --- Generation logic ---

function generateEntry(word: WordEntry, index: number): FixtureEntry {
  const [headword, vietnamese, partOfSpeech, definition, example, aliases] = word;

  const entry: FixtureEntry = {
    headword,
    sourceLanguage: "en",
    frequencyRank: index + 1,
    aliases: aliases
      ? aliases.map((a) => ({ alias: a, type: "inflection" as const }))
      : [],
    senses: [
      {
        partOfSpeech,
        definition,
        example,
        tags: [],
        usageRank: 1,
        translations: [
          {
            targetLanguage: "vi",
            translation: vietnamese,
            isPrimary: true,
            rank: 1,
            confidence: 0.95,
            status: "reviewed",
            sourceType: "seed",
            sourceName: "seed-common-1000",
          },
        ],
      },
    ],
  };

  return entry;
}

function main() {
  const entries = WORDS.map((word, i) => generateEntry(word, i));

  // Deduplicate by normalized headword (case-insensitive)
  const seen = new Set<string>();
  const unique = entries.filter((e) => {
    const key = e.headword.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  // Build headword set for alias collision filtering
  const headwordNorms = new Set(unique.map((e) => e.headword.toLowerCase()));

  // Remove aliases that collide with another entry's headword
  for (const entry of unique) {
    const entryNorm = entry.headword.toLowerCase();
    if (entry.aliases) {
      entry.aliases = entry.aliases.filter(
        (a) => !headwordNorms.has(a.alias.toLowerCase()) || a.alias.toLowerCase() === entryNorm
      );
      if (entry.aliases.length === 0) delete entry.aliases;
    }
  }

  const outputPath = join(
    process.cwd(),
    "prisma/data/dictionary/en-vi/common-1000.json"
  );
  writeFileSync(outputPath, JSON.stringify(unique, null, 2), "utf8");

  console.log(
    `Generated ${unique.length} entries to ${outputPath} (${(unique.length === WORDS.length ? "no duplicates" : `${WORDS.length - unique.length} duplicates removed`)})`
  );
}

main();
